function TemplateDetails({template,onBack,onTry,onAdd}){const [playing,setPlaying]=useState(false);return <div className="details-page"><header className="gallery-header"><button className="gallery-brand brand" onClick={onBack}><span className="brand-icon"><Heart size={17} fill="currentColor"/></span> surprise<span>link</span></button><div className="gallery-breadcrumb"><button onClick={onBack}>All templates</button><ChevronRight size={13}/><b>{template.name}</b></div><div className="detail-rating">★★★★★ <span>5.0</span></div></header><main className="detail-main"><button className="back-link" onClick={onBack}>← All templates</button><section className="detail-layout"><div className="detail-media-column"><button className={`detail-demo art-${template.theme} ${playing?'demo-playing':''}`} onClick={()=>setPlaying(!playing)}><span className="detail-demo-spark">✦　♡　✦</span><span className="detail-demo-icon">{template.icon}</span><span className="detail-demo-title">{template.name}</span><span className="detail-demo-hint">{playing?'Previewing the experience':'Play a quick preview'}</span><span className="detail-play"><Play size={21} fill="currentColor"/></span><span className="demo-watermark">SURPRISELINK · FREE PREVIEW</span></button><div className="detail-full-preview"><Sparkles size={16}/> Preview updates as you customize this design</div><section className="included-card"><h2><Sparkles size={15}/> What’s included</h2><div><span><Check/> Editable recipient name and message</span><span><Music2/> Optional song link</span><span><WandSparkles/> {['digital-letter','kawaii-letter','digital-diary'].includes(template.id)?'Page-by-page interactive story':'One-page themed gift experience'}</span><span><ShieldCheck/> Mobile-friendly gift page</span><span><Camera/> Local photo preview in the editor</span><span><Link2/> Shareable text link and QR code</span></div></section></div><div className="detail-copy"><div className="eyebrow"><Heart size={12} fill="currentColor"/> FREE LAUNCH OFFER</div><h1>{template.name}</h1><p className="detail-description">{template.id==='digital-diary'?'A PIN-protected diary cover opens into a two-page letter spread, a three-photo scrapbook, a music page, a YouTube page, and a closing note.':template.description+' Personalize your words and choose a distinct design. Photos and custom backgrounds preview on this device only; shared links currently include text until cloud storage and publishing are connected.'}</p><div className="customize-card"><h2>Make it yours</h2><p>Every template is free during our launch offer. Save your draft and share it with a link or QR code.</p><button className="primary detail-try" onClick={()=>onTry(template)}><Play size={17}/> START CUSTOMIZING FOR FREE</button><small>Keep editing your local draft at any time.</small></div><div className="launch-offer-price"><s>${template.price.toFixed(2)}</s><strong>$0</strong><span>FREE LAUNCH OFFER</span></div><section className="how-template"><h3>How to use this template</h3><ol><li>Choose a design and personalize it</li><li>Save the draft on this device</li><li>Share with a link or QR code</li></ol></section></div></section></main><footer className="gallery-footer"><button onClick={onBack}>← Browse all templates</button><span>Every SurpriseLink design is free during launch.</span></footer></div>}
