 const [expiresAt,setExpiresAt]=useState(()=>{if(purchased)return 0;let value=Number(localStorage.getItem(trialKey));if(!value){value=Date.now()+7*24*60*60*1000;localStorage.setItem(trialKey,String(value));}return value;});
 React.useEffect(()=>{const timer=setInterval(()=>setNow(Date.now()),1000);return()=>clearInterval(timer)},[]);
