function Editable({label,value,onChange,area=false,maxLength,inputMode}){return <label className="editable-field"><span>{label}</span>{area?<textarea rows="4" maxLength={maxLength} value={value||''} onChange={e=>onChange(e.target.value)}/>:<input maxLength={maxLength} inputMode={inputMode} value={value||''} onChange={e=>onChange(e.target.value)}/>}</label>}
function getYoutubeId(url=''){const m=url.match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|embed\/|shorts\/))([\w-]{11})/);return m?.[1]||''}
function EyeIcon(){return <span aria-hidden="true">◉</span>}
function CassettePlayer({song,heading,caption}){const match=(song||'').match(/open\.spotify\.com\/(track|album|playlist|episode)\/([\w]+)/);const spotify=match?`https://open.spotify.com/embed/${match[1]}/${match[2]}`:'';return <><h2>{heading||'Our little soundtrack'}</h2><div className="cassette-player"><div className="cassette-topline"><span>SURPRISELINK MIXTAPE</span><span>♥ PLAY SIDE A ♥</span></div><div className="cassette-label"><i>♫</i><b>{song?'A song I chose for you':'Our song'}</b><small>PLAY IT WHEN YOU MISS ME</small></div><div className="cassette-window"><span></span><i></i><span></span></div><div className="cassette-bottomline"><span>◉────────◉</span><span>LOVE MIX · 01</span></div></div>{spotify?<iframe className="spotify-player" src={spotify} title="A song chosen for you" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" loading="lazy"/>:song?<a className="cassette-open-link" href={song} target="_blank" rel="noreferrer"><Play size={13} fill="currentColor"/> Play our song</a>:<p className="cassette-help">Add a Spotify track, album, or playlist link to make this mixtape play.</p>}<p>{caption||'A song that always brings me back to you.'}</p></>}
function createFourDigitPasscode(){const values=new Uint32Array(1),limit=Math.floor(2**32/9000)*9000;do{crypto.getRandomValues(values)}while(values[0]>=limit);return String(1000+values[0]%9000)}
function DiaryPageFields({page,gift,set,setPhoto,generatePasscode}){if(page===0)return <><Editable label="COVER INTRO" value={gift.diaryCoverKicker} onChange={v=>set('diaryCoverKicker',v)}/><Editable label="DIARY TITLE" value={gift.diaryTitle} onChange={v=>set('diaryTitle',v)}/><Editable label="COVER DESCRIPTION" value={gift.diarySubtitle} onChange={v=>set('diarySubtitle',v)}/><Editable label="DIARY PASSCODE · 4 DIGITS" value={gift.diaryPassword} onChange={v=>set('diaryPassword',v.replace(/\D/g,'').slice(0,4))} maxLength={4} inputMode="numeric"/><button type="button" className="passcode-generate" onClick={generatePasscode}><LockKeyhole size={13}/> Generate a passcode</button><small className="diary-pin-help">A new random 4-digit passcode will replace the current one.</small><Editable label="COVER SIGN-OFF" value={gift.diaryCoverFooter} onChange={v=>set('diaryCoverFooter',v)}/></>;if(page===1)return <><Editable label="PAGE TITLE" value={gift.letterHeading} onChange={v=>set('letterHeading',v)}/><Editable label="LETTER TEXT" value={gift.message} onChange={v=>set('message',v)} area/><Editable label="SIGN-OFF TEXT" value={gift.letterSignoff} onChange={v=>set('letterSignoff',v)}/><Editable label="YOUR NAME" value={gift.from} onChange={v=>set('from',v)}/></>;if(page===2)return <><Editable label="MEMORY PAGE INTRO" value={gift.memoryKicker} onChange={v=>set('memoryKicker',v)}/><Editable label="PAGE TITLE" value={gift.memoryHeading} onChange={v=>set('memoryHeading',v)}/><Editable label="SHORT DESCRIPTION" value={gift.memoryIntro} onChange={v=>set('memoryIntro',v)} area/>{[0,1,2].map(i=><div className="memory-edit" key={i}><label className="field-label">PHOTO {i+1}<input type="file" accept="image/*" onChange={e=>setPhoto(i,e.target.files?.[0])}/></label>{gift.photos?.[i]&&<small className="photo-selected">Photo added · choose another to replace</small>}<Editable label={`PHOTO ${i+1} CAPTION`} value={gift[`caption${i+1}`]} onChange={v=>set(`caption${i+1}`,v)}/></div>)}</>;if(page===3)return <><Editable label="MUSIC PAGE EYEBROW" value={gift.musicKicker} onChange={v=>set('musicKicker',v)}/><Editable label="MUSIC TITLE" value={gift.videoHeading} onChange={v=>set('videoHeading',v)}/><Editable label="MUSIC DESCRIPTION" value={gift.videoCaption} onChange={v=>set('videoCaption',v)} area/><Editable label="SPOTIFY OR MUSIC LINK" value={gift.song} onChange={v=>set('song',v)}/></>;if(page===4)return <><Editable label="VIDEO PAGE EYEBROW" value={gift.videoKicker} onChange={v=>set('videoKicker',v)}/><Editable label="VIDEO TITLE" value={gift.diaryVideoHeading} onChange={v=>set('diaryVideoHeading',v)}/><Editable label="VIDEO DESCRIPTION" value={gift.diaryVideoCaption} onChange={v=>set('diaryVideoCaption',v)} area/><Editable label="YOUTUBE VIDEO LINK" value={gift.videoUrl} onChange={v=>set('videoUrl',v)}/></>;return <><Editable label="CLOSING PAGE EYEBROW" value={gift.closingKicker} onChange={v=>set('closingKicker',v)}/><Editable label="LAST PAGE TITLE" value={gift.finalHeading} onChange={v=>set('finalHeading',v)}/><Editable label="SHORT DESCRIPTION" value={gift.finalText} onChange={v=>set('finalText',v)} area/><Editable label="FROM LABEL" value={gift.closingFromLabel} onChange={v=>set('closingFromLabel',v)}/><Editable label="FROM NAME" value={gift.from} onChange={v=>set('from',v)}/><Editable label="CLOSING NOTE" value={gift.diaryCloseNote} onChange={v=>set('diaryCloseNote',v)}/></>}
function DiaryScene({page,gift,onEnter,pinEntry,setPinEntry,pinError,direction='next'}){
 const video=getYoutubeId(gift.videoUrl||'');
 if(page===0)return <div className={`diary-cover-page diary-turn-${direction}`}><div className="diary-cover-book"><span className="diary-cover-kicker">{gift.diaryCoverKicker||'A little book of us'}</span><span className="diary-cover-ornament">❀</span><h2>{gift.diaryTitle||'Our Digital Diary'}</h2><p>{gift.diarySubtitle||'Memories made with love'}</p><label className="diary-pin-label"><span>DIARY PIN · 4 DIGITS</span><div className="diary-pin-inputs" role="group" aria-label="Four digit diary PIN">{Array.from({length:4},(_,i)=><input key={i} type="text" inputMode="numeric" maxLength={1} autoComplete="off" value={pinEntry[i]||''} aria-label={"PIN digit "+(i+1)} onFocus={e=>e.currentTarget.select()} onChange={e=>{const next=pinEntry.split('');next[i]=e.target.value.replace(/\D/g,'').slice(-1);setPinEntry(next.join(''));if(next[i]&&i<3)e.target.nextElementSibling?.focus()}} onKeyDown={e=>{if(e.key==='Backspace'&&!pinEntry[i]&&i>0)e.currentTarget.previousElementSibling?.focus();if(e.key==='Enter')onEnter()}}/>)}</div></label>{pinError&&<small className="diary-pin-error" role="alert">{pinError}</small>}<button type="button" onClick={onEnter}>Enter diary <ArrowRight size={14}/></button><span className="diary-cover-from">{gift.diaryCoverFooter||'Made for you, with love ♡'}</span></div></div>;
 if(page===1)return <div className={`diary-book-spread diary-turn-${direction}`}><section className="diary-book-page diary-blank-page"/><section className="diary-book-page diary-letter-page"><span className="diary-page-number">01 · A PAGE FROM MY HEART</span><h2>{gift.letterHeading||'A page from my heart...'}</h2><div className="diary-scroll-window"><p>{gift.message||'Write a little note to someone you love.'}</p></div><span className="diary-page-signature">{gift.letterSignoff||'With love'}, {gift.from||'someone who loves you'} ♡</span></section></div>;
 if(page===2)return <div className={`diary-book-spread diary-turn-${direction}`}><section className="diary-book-page diary-memory-intro"><span className="diary-page-number">02 · OUR MEMORIES</span><span>{gift.memoryKicker||'kept close, always'}</span><h2>{gift.memoryHeading||'Pages I keep close'}</h2><p>{gift.memoryIntro||'Three little moments, saved here for us.'}</p><i>✿　♡　✿</i></section><section className="diary-book-page diary-gallery-page"><div className="diary-gallery-grid">{[0,1,2].map(i=><article className={`diary-memory-row diary-memory-row-${i+1}`} key={i}>{i===1?<p>{gift[`caption${i+1}`]||`A little memory ${i+1}`}</p>:null}{gift.photos?.[i]?<img src={gift.photos[i]} alt={gift[`caption${i+1}`]||`Diary memory ${i+1}`}/>:<div className="diary-photo-empty" aria-label={`Photo ${i+1} not added`}/>}{i!==1?<p>{gift[`caption${i+1}`]||`A little memory ${i+1}`}</p>:null}</article>)}</div></section></div>;
 if(page===3)return <div className={`diary-book-spread diary-turn-${direction}`}><section className="diary-book-page diary-blank-page"/><section className="diary-book-page diary-media-page"><span className="diary-page-number">03 · {gift.musicKicker||'OUR SOUNDTRACK'}</span><CassettePlayer song={gift.song} heading={gift.videoHeading||'Our little soundtrack'} caption={gift.videoCaption}/></section></div>;
 if(page===4)return <div className={`diary-book-spread diary-turn-${direction}`}><section className="diary-book-page diary-blank-page"/><section className="diary-book-page diary-media-page"><span className="diary-page-number">04 · {gift.videoKicker||'A MOMENT IN MOTION'}</span>{video?<div className="video-frame"><iframe src={`https://www.youtube-nocookie.com/embed/${video}`} title={gift.diaryVideoHeading||'A video memory'} allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen/></div>:<div className="video-frame"><div className="video-placeholder"><span>▶</span><b>{gift.diaryVideoHeading||'A little video for you'}</b><small>Add a YouTube link in the editor</small></div></div>}<h2>{gift.diaryVideoHeading||'A little video for you'}</h2><p>{gift.diaryVideoCaption||'A moment I wanted to keep with you.'}</p></section></div>;
 return <div className={`diary-closing-page diary-turn-${direction}`}><span className="diary-page-number">{gift.closingKicker||'THE LAST PAGE'}</span><span className="diary-close-flower">❀</span><h2>{gift.finalHeading||gift.diaryTitle||'Our Digital Diary'}</h2><p>{gift.finalText||'A few little pages, filled with a lot of love.'}</p><span className="diary-page-signature">{gift.closingFromLabel||'FROM'}&nbsp; {gift.from||'someone who loves you'}</span><span className="diary-close-note">{gift.diaryCloseNote||'Close this little book and keep the memories ♡'}</span></div>
}
function TemplateEditor({template,gift,setGift,onBack,onCart,onAdd,onCopy,copied}){
  const photoInput=React.useRef(null);const [photoMessage,setPhotoMessage]=useState('');const [qrUrl,setQrUrl]=useState('');
  const addPhotos=fileList=>{const current=gift.photos||[];const files=[...fileList].slice(0,Math.max(0,3-current.length));if(!files.length){setPhotoMessage('You can add up to three photos.');return;}if(files.some(file=>file.size>1024*1024)){setPhotoMessage('Please choose photos smaller than 1 MB each.');return;}Promise.all(files.map(file=>new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>resolve(null);reader.readAsDataURL(file)}))).then(images=>{const additions=images.filter(Boolean);setGift(value=>({...value,photos:[...(value.photos||[]),...additions].slice(0,3)}));setPhotoMessage('')})};
 return <div className="edit-page"><header className="edit-header"><button className="gallery-brand brand" onClick={onBack}><span className="brand-icon"><Heart size={17} fill="currentColor"/></span> surprise<span>link</span></button><div className="editor-crumb"><button onClick={onBack}>All templates</button><ChevronRight size={13}/><b>{template.name}</b></div><span className="template-free-badge">Free to create and share</span></header>
 <main className="edit-main"><div className="edit-heading"><div><button className="back-link" onClick={onBack}>← Back to all templates</button><div className="eyebrow">TEMPLATE EDITOR · {template.tag}</div><h1>Make <em>{template.name}</em> yours.</h1><p>Change the words and see them update in this design.</p></div><span className="autosave-pill"><i/> Saved on this device</span></div>
  <div className="editor-layout"><section className="editor-controls"><div className="editor-section-title"><span>01</span><div><b>Your message</b><small>Make it sound like you.</small></div></div><label>THEIR NAME<input value={gift.name} onChange={e=>setGift({...gift,name:e.target.value})} placeholder="Their name"/></label><label>FROM<input value={gift.from} onChange={e=>setGift({...gift,from:e.target.value})} placeholder="Your name"/></label><label>YOUR NOTE<textarea value={gift.message} onChange={e=>setGift({...gift,message:e.target.value})} rows="5" maxLength="280"/><small className="edit-counter">{gift.message.length}/280</small></label><div className="editor-section-title media-title"><span>02</span><div><b>Little extras</b><small>Optional touches for your gift.</small></div></div><label>ADD A SONG LINK<div className="song-input"><Music2 size={15}/><input value={gift.song} onChange={e=>setGift({...gift,song:e.target.value})} placeholder="Spotify or YouTube URL"/></div></label><div className="photo-upload-wrap"><input ref={photoInput} className="photo-input-hidden" type="file" accept="image/*" multiple aria-label="Choose gift photos" onChange={e=>{addPhotos(e.target.files);e.target.value=''}}/><button type="button" className="photo-upload" onClick={()=>photoInput.current?.click()} disabled={(gift.photos||[]).length>=3}><ImagePlus size={17}/><span><b>{(gift.photos||[]).length>=3?'Three photos added':'Add photos from your device'}</b><small>Local preview only · up to 3 photos · 1 MB each</small></span><ChevronRight size={15}/></button>{photoMessage&&<p className="photo-upload-message" role="status">{photoMessage}</p>}{gift.photos?.length>0&&<div className="local-photo-grid">{gift.photos.map((photo,index)=><div className="local-photo-thumb" key={`${index}-${photo.slice(0,24)}`}><img src={photo} alt={`Gift memory ${index+1}`}/><button type="button" aria-label={`Remove photo ${index+1}`} onClick={()=>setGift(value=>({...value,photos:(value.photos||[]).filter((_,i)=>i!==index)}))}><X size={12}/></button></div>)}</div>}<p className="local-photo-note">Photos stay on this device and won't appear in shared links until cloud publishing is connected.</p><BackgroundImageControl image={gift.backgroundImage} onChange={image=>setGift(value=>({...value,backgroundImage:image}))}/></div><div className="editor-buttons"><button className="primary" onClick={async()=>{const url=await onCopy();if(url)setQrUrl(url)}}><Link2 size={15}/> Share free gift + QR</button><button className="secondary-share" onClick={()=>{localStorage.setItem(`surpriselink-draft-${template.id}`,JSON.stringify(gift));alert('Your free draft is saved in this browser.')}}><Check size={15}/> Save free draft</button></div><p className="editor-disclaimer"><LockKeyhole size={12}/> Free to edit and share. Photos and custom backgrounds remain on this device until cloud publishing is connected.</p></section>
   <section className="editor-preview-wrap"><div className="editor-preview-top"><span>LIVE PREVIEW</span><span><i/> {template.name}</span></div><EditorDesign template={template} gift={gift}/><p className="preview-explainer">This template has its own colors, artwork, and page layout.</p></section></div>
 </main><footer className="gallery-footer"><button onClick={onBack}>← Browse all 22 designs</button><span>One design. Made personal.</span></footer>{qrUrl&&<QRShareDialog url={qrUrl} onClose={()=>setQrUrl('')}/>}</div>
}
const qrStyles=[['square','Square'],['rounded','Rounded'],['circle','Circle frame'],['heart','Heart frame'],['diamond','Diamond frame'],['flower','Flower frame'],['star','Star frame'],['ticket','Ticket frame'],['hexagon','Hexagon frame'],['scallop','Scallop frame']];
function downloadStyledQR(dataUrl,style){const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=440;canvas.height=440;const ctx=canvas.getContext('2d');ctx.fillStyle='#f5dfe2';ctx.strokeStyle='#bd7183';ctx.lineWidth=8;ctx.beginPath();if(style==='circle'||style==='scallop')ctx.arc(220,220,210,0,Math.PI*2);else if(style==='heart'){ctx.moveTo(220,385);ctx.bezierCurveTo(190,360,35,265,35,150);ctx.bezierCurveTo(35,55,150,38,220,125);ctx.bezierCurveTo(290,38,405,55,405,150);ctx.bezierCurveTo(405,265,250,360,220,385)}else if(style==='diamond'){ctx.moveTo(220,15);ctx.lineTo(425,220);ctx.lineTo(220,425);ctx.lineTo(15,220);ctx.closePath()}else if(style==='star'){for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,r=i%2?170:210,x=220+Math.cos(a)*r,y=220+Math.sin(a)*r;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.closePath()}else if(style==='hexagon'){for(let i=0;i<6;i++){const a=Math.PI/3*i-Math.PI/6,x=220+Math.cos(a)*210,y=220+Math.sin(a)*210;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.closePath()}else if(style==='flower'){for(let i=0;i<8;i++){const a=i*Math.PI/4;ctx.moveTo(220,220);ctx.arc(220+Math.cos(a)*90,220+Math.sin(a)*90,118,a-Math.PI/2,a+Math.PI/2)}ctx.closePath()}else if(style==='ticket'){ctx.roundRect(14,14,412,412,34);ctx.moveTo(14,150);ctx.arc(14,178,28,-Math.PI/2,Math.PI/2);ctx.moveTo(426,150);ctx.arc(426,178,28,Math.PI/2,-Math.PI/2)}else if(style==='scallop'){for(let i=0;i<16;i++){const a=i*Math.PI/8;ctx.arc(220+Math.cos(a)*184,220+Math.sin(a)*184,30,a-Math.PI/2,a+Math.PI/2)}ctx.closePath()}else if(style==='rounded')ctx.roundRect(14,14,412,412,48);else ctx.rect(14,14,412,412);ctx.fill();ctx.stroke();ctx.fillStyle='#fffaf7';ctx.fillRect(70,70,300,300);ctx.drawImage(image,75,75,290,290);const a=document.createElement('a');a.download=`surpriselink-qr-${style}.png`;a.href=canvas.toDataURL('image/png');a.click()};image.src=dataUrl}
function QRShareDialog({url,onClose}){const localOnly=/^https?:\/\/(localhost|127\.0\.0\.1)(:\d+)?/i.test(url);const [style,setStyle]=useState('rounded');const [image,setImage]=useState('');const [error,setError]=useState('');React.useEffect(()=>{let alive=true;QRCode.toDataURL(url,{width:320,margin:2,errorCorrectionLevel:'H',color:{dark:'#5d3142',light:'#fffaf7'}}).then(value=>{if(alive){setImage(value);setError('')}}).catch(()=>{if(alive)setError('This link is too long for a QR code. Remove some text and try again.')});return()=>{alive=false}},[url]);return <Modal title="Share your free gift" onClose={onClose}><div className="qr-share"><p>Your gift link is ready. Choose a frame, then save the QR image to share it.</p><div className={`qr-frame qr-frame-${style}`}><div className="qr-inner">{image?<img src={image} alt="QR code for your SurpriseLink"/>:<span>♡</span>}</div></div><div className="qr-style-grid" aria-label="QR frame styles">{qrStyles.map(([id,label])=><button type="button" key={id} className={style===id?'selected':''} onClick={()=>setStyle(id)}>{label}</button>)}</div>{error&&<p className="qr-error" role="alert">{error}</p>}<div className="qr-link-row"><input readOnly value={url} aria-label="Share link"/><button onClick={async()=>{try{await navigator.clipboard.writeText(url)}catch{window.prompt('Copy this link:',url)}}}>Copy link</button></div><button type="button" className="primary qr-download" disabled={!image} onClick={()=>downloadStyledQR(image,style)}>Download shaped QR <ArrowRight size={14}/></button><small className="qr-private-note">{localOnly?<>This link uses localhost and only opens on this computer. To scan it on a phone, deploy the site and set <code>VITE_PUBLIC_SITE_URL</code> to its public web address.</>:<>This QR opens the shared gift page. Photos and custom backgrounds are not included until cloud media hosting is added.</>}</small></div></Modal>}
function Modal({title,onClose,children}) { return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="modal" role="dialog" aria-modal="true"><header><h2>{title}</h2><button className="modal-close" onClick={onClose} aria-label="Close"><X size={19}/></button></header>{children}</section></div>; }
function CartContent({cart,total,onRemove,onBrowse,onCheckout}) { return <div className="cart-content">{cart.length===0?<div className="empty-cart"><span>♡</span><h3>Your cart is taking a little nap.</h3><p>Pick a template to make someone's day.</p><button className="primary" onClick={onBrowse}>Browse templates <ArrowRight size={15}/></button></div>:<><div className="cart-items">{cart.map(item=><div className="cart-item" key={item.id}><span className="cart-item-art">{item.icon}</span><div><b>{item.name}</b><small>Personal digital gift template</small></div><strong>${item.price.toFixed(2)}</strong><button onClick={()=>onRemove(item.id)} aria-label={`Remove ${item.name}`}><Trash2 size={15}/></button></div>)}</div><div className="cart-total"><span>Total</span><b>${total.toFixed(2)} <small>USD</small></b></div><button className="primary full-button" onClick={onCheckout}>Continue to checkout <ArrowRight size={15}/></button><p className="secure-note"><LockKeyhole size={13}/> Secure payment setup is not connected in this preview.</p></>}</div>; }
function CheckoutContent({cart,total,onDone}) { const [email,setEmail]=useState(''); const [name,setName]=useState(''); return <form className="checkout-form" onSubmit={e=>{e.preventDefault();onDone()}}><p className="checkout-intro">Your templates are ready. Add your details to continue.</p><label>NAME<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Your name"/></label><label>EMAIL<input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></label><div className="checkout-summary"><span>{cart.length} {cart.length===1?'template':'templates'}</span><b>${total.toFixed(2)} USD</b></div><button className="primary full-button">Place demo order <ArrowRight size={15}/></button><p className="secure-note"><LockKeyhole size={13}/> Demo only — no payment details are collected.</p></form>; }
function InfoModal({title,onClose,icon,children}) { return <Modal title={title} onClose={onClose}><div className="info-content"><span>{icon}</span><p>{children}</p><button className="primary" onClick={onClose}>Got it <Check size={15}/></button></div></Modal>; }
function GoogleMark(){return <svg aria-hidden="true" width="18" height="18" viewBox="0 0 48 48"><path fill="#FFC107" d="M43.6 24.5c0-1.4-.1-2.8-.4-4.1H24v7.8h11a9.4 9.4 0 0 1-4.1 6.2v5.1h6.6c3.9-3.6 6.1-8.8 6.1-15z"/><path fill="#FF3D00" d="M24 44c5.5 0 10.1-1.8 13.5-4.8l-6.6-5.1c-1.8 1.2-4.1 2-6.9 2-5.3 0-9.8-3.6-11.4-8.4H5.8V33C9.2 39.5 16.1 44 24 44z"/><path fill="#4CAF50" d="M12.6 27.7A12 12 0 0 1 12 24c0-1.3.2-2.6.6-3.7V15H5.8A20 20 0 0 0 4 24c0 3.2.8 6.2 2.2 9l6.4-5.3z"/><path fill="#1976D2" d="M24 11.9c3 0 5.7 1 7.8 3.1l5.8-5.8C34.1 6 29.5 4 24 4 16.1 4 9.2 8.5 5.8 15l6.8 5.3c1.6-4.8 6.1-8.4 11.4-8.4z"/></svg>;}
function GiftLanding({gift}) { const [opened,setOpened]=useState(false);const design=templates.find(t=>t.id===gift.template)||templates[0]; if(['digital-letter','kawaii-letter','digital-diary'].includes(design.id))return <RecipientStory gift={gift} template={design}/>;return <div className={`gift-page gift-theme-${design.theme}`}><div className="gift-page-glow"></div><a className="brand gift-brand" href="/"><span className="brand-icon"><Heart size={17} fill="currentColor"/></span> surprise<span>link</span></a><main className={`gift-page-card recipient-theme recipient-${design.theme}`}><div className="recipient-art"><span>{design.icon}</span><i>{themeOrnament(design.theme)}</i></div><div className="gift-page-spark">{themeOrnament(design.theme)}　♡　{themeOrnament(design.theme)}</div><div className="gift-page-heart"><Heart size={23} fill="currentColor"/></div><div className="gift-page-occasion">{design.tag}</div><h1>{opened?`For ${gift.name||'you'}, with love`:`A little something for ${gift.name||'you'}`}</h1>{opened&&<><p className="gift-page-message">{gift.message}</p><div className="gift-page-signature">With love, {gift.from||'someone special'} ♡</div>{gift.song&&<a className="gift-page-song" href={gift.song} target="_blank" rel="noreferrer"><Music2 size={15}/> A song picked for you</a>}</>}<button className="primary gift-open" onClick={()=>setOpened(!opened)}>{opened?'Read it again':'Open your surprise'} <Heart size={15} fill="currentColor"/></button></main><div className="gift-page-footer">A little love, delivered with <Heart size={12} fill="currentColor"/></div></div>; }
function DiaryRecipientStory({gift}){const [scene,setScene]=useState(0);const [direction,setDirection]=useState('next');const [pinEntry,setPinEntry]=useState('');const [pinError,setPinError]=useState('');const goToPage=next=>{setDirection(next>=scene?'next':'previous');setScene(next)};const enter=()=>{if(String(pinEntry).length===4&&String(pinEntry)===String(gift.diaryPassword||'').slice(0,4)){setPinError('');goToPage(1)}else setPinError('That PIN did not match. Please try again.')};return <div className="recipient-story recipient-diary-story"><header><a className="brand" href="/"><span className="brand-icon"><Heart size={16} fill="currentColor"/></span> surprise<span>link</span></a><button type="button" className="recipient-restart" onClick={()=>{setPinEntry('');setPinError('');goToPage(0)}}><RotateCcw size={14}/><span>Restart</span></button><span>A little story for {gift.name||'you'} ♡</span></header><main className={`recipient-story-canvas bg-${gift.background||'gingham'} has-watermark diary-turn-${direction}`} style={gift.backgroundImage?{backgroundImage:`linear-gradient(rgba(255,249,246,.5),rgba(255,249,246,.5)),url(${gift.backgroundImage})`,backgroundPosition:'center',backgroundSize:'cover'}:undefined}><DiaryScene page={scene} gift={gift} pinEntry={pinEntry} setPinEntry={setPinEntry} pinError={pinError} direction={direction} onEnter={enter}/></main><nav className="recipient-story-nav"><button disabled={scene===0} onClick={()=>goToPage(Math.max(0,scene-1))}>‹ Previous page</button><div>{Array.from({length:6},(_,i)=><button key={i} className={scene===i?'active':''} aria-label={`Go to page ${i+1}`} onClick={()=>goToPage(i)}/>)}</div><button disabled={scene===0||scene===5} onClick={()=>goToPage(Math.min(5,scene+1))}>{scene===5?'Close the diary':'Turn page →'}</button></nav><footer>Made with love on SurpriseLink <Heart size={11} fill="currentColor"/></footer></div>}
function RecipientStory({gift,template}){if(template.id==='digital-diary')return <DiaryRecipientStory gift={gift}/>;const [scene,setScene]=useState(0);const [opened,setOpened]=useState(false);const [pinPrompt,setPinPrompt]=useState(false);const [pinEntry,setPinEntry]=useState('');const [pinError,setPinError]=useState('');const props=[gift.caption1||'A favorite moment',gift.caption2||'A day to remember',gift.caption3||'My favorite smile'];const photoIndexes=(gift.photos||[]).filter(Boolean).length===1?[(gift.photos||[]).findIndex(Boolean)]:[0,1,2];const video=getYoutubeId(gift.videoUrl||'');return <div className="recipient-story"><header><a className="brand" href="/"><span className="brand-icon"><Heart size={16} fill="currentColor"/></span> surprise<span>link</span></a><span>A little story for {gift.name||'you'} ♡</span></header><main className={`recipient-story-canvas bg-${gift.background||'gingham'} has-watermark`} style={gift.backgroundImage?{backgroundImage:`linear-gradient(rgba(255,249,246,.5),rgba(255,249,246,.5)),url(${gift.backgroundImage})`,backgroundPosition:'center',backgroundSize:'cover'}:undefined}>
 {scene===0&&<div className={`letter-cover-scene ${template.id==='digital-diary'?'diary-cover-stage':''}`}><div className="cover-flower flower-left">✿</div><div className="cover-flower flower-right">✿</div><div className="cover-stars">✦　☾　✦</div>{template.id==='digital-diary'?<><button className={`diary-cover ${opened?'diary-open':''}`} onClick={()=>gift.diaryPassword?setPinPrompt(true):setOpened(true)}><span>MY LITTLE DIGITAL DIARY</span><i>♡</i><strong>{gift.name||'Someone special'}’s memories</strong><small>{gift.diaryPassword?'PIN LOCKED · tap to unlock':'tap to open'}</small></button>{pinPrompt&&!opened&&<div className="diary-pin-card"><b>THIS DIARY IS JUST FOR YOU</b><span>Enter the little code to open it</span><input type="password" inputMode="numeric" maxLength={8} value={pinEntry} onChange={e=>setPinEntry(e.target.value)} aria-label="Diary password" placeholder="Enter password"/><button onClick={()=>{if(pinEntry===String(gift.diaryPassword||'')){setPinError('');setOpened(true);setPinPrompt(false)}else setPinError('That code didn’t match. Try again.')}}>Unlock diary</button>{pinError&&<small role="alert">{pinError}</small>}<button className="pin-cancel" onClick={()=>{setPinPrompt(false);setPinError('')}}>Cancel</button></div>}</>:<div className={`letter-envelope ${opened?'envelope-open':''}`} onClick={()=>setOpened(true)} role="button" tabIndex="0"><div className="envelope-back"></div><div className="envelope-paper"><span>{gift.name||'My favorite person'}</span><p>{gift.message?.slice(0,70)}</p></div><div className="envelope-flap"></div><div className="envelope-seal">♥</div></div>}<p className="cover-hint">{gift.coverHint||'Tap the seal to open ♥'}</p>{opened&&<div className="flower-burst">{Array.from({length:34},(_,i)=><i key={i} style={{'--dx':`${Math.cos(i/34*Math.PI*2)*(100+(i%5)*22)}px`,'--dy':`${Math.sin(i/34*Math.PI*2)*(100+(i%5)*22)}px`,'--delay':`${(i%9)*.035}s`}}>{['✿','❀','✦','♡'][i%4]}</i>)}</div>}</div>}
 {scene===1&&<div className={`letter-paper-scene ${template.id==='digital-diary'?'diary-paper-scene':''}`}><div className="paper-top-flower">✿　❀　✿</div><span className="paper-eyebrow">{template.id==='digital-diary'?'A PAGE FROM OUR DIARY':`A LITTLE LETTER FOR ${String(gift.name||'YOU').toUpperCase()}`}</span><h2>{gift.letterHeading||'A letter for you...'}</h2><div className="paper-divider">♡</div><p>{gift.message}</p><span className="paper-signature">All my love,<br/><em>{gift.from||'someone who loves you'}</em></span></div>}
 {scene===2&&<div className="memory-scene"><div className="memory-heading">{gift.memoryHeading||'Our memories'}<small>A few moments I keep close</small></div><div className={`memory-grid ${photoIndexes.length===1?'memory-grid-single':''}`}>{photoIndexes.map(i=><div className={`memory-card memory-${i}`} key={i}><label className="memory-image">{gift.photos?.[i]?<img src={gift.photos[i]} alt={props[i]}/>:<span>{['🌷','🌅','💗'][i]}</span>}<b>♥</b></label><p>{props[i]}</p></div>)}</div></div>}
 {scene===3&&<div className={`video-scene ${template.id==='digital-diary'?'diary-music-scene':''}`}>{template.id==='digital-diary'?<CassettePlayer song={gift.song} heading={gift.videoHeading} caption={gift.videoCaption}/>:<>{video?<div className="video-frame"><iframe src={`https://www.youtube-nocookie.com/embed/${video}`} title="A video memory" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen/></div>:<div className="video-frame"><div className="video-placeholder"><span>▶</span><b>A little video for you</b><small>Add a YouTube link in your editor</small></div></div>}<h2>{gift.videoHeading||'A little video for you'}</h2><p>{gift.videoCaption||'A moment I wanted to keep with you.'}</p></>}</div>}
 {scene===4&&<div className="final-scene"><span className="final-sparkles">✦　♡　✦</span><div className="final-heart">♥</div><h2>{gift.finalHeading||'One last little thing...'}</h2><p>{gift.finalText||'I hope you always remember how loved you are.'}</p><span className="final-from">Always yours, {gift.from||'with love'}</span><div className="final-confetti">✿　✦　❀　♡　✧</div></div>}
 </main><nav className="recipient-story-nav"><button disabled={scene===0} onClick={()=>{setScene(s=>s-1);setOpened(false)}}>← Previous</button><div>{[0,1,2,3,4].map(i=><button key={i} className={scene===i?'active':''} aria-label={`Scene ${i+1}`} onClick={()=>{setScene(i);setOpened(false)}}/>)}</div><button disabled={scene===0&&!opened||scene===4} onClick={()=>{setScene(s=>Math.min(4,s+1));setOpened(false)}}>{scene===4?'The End':'Continue →'}</button></nav><footer>Made with love on SurpriseLink <Heart size={11} fill="currentColor"/></footer></div>;}
export default App;
